bool damageData[2][level_width*64][level_height*32];

void paintSpike(int x, int y, int dir) {
	int baseX = (x-1) * 64;
	int baseY = (y-1) * 32;
	for (int cx = (x-1) * 64; cx < (x+2) * 64; cx++) {
		for (int cy = (y-1) * 32; cy < (y+3) * 32; cy++) {
			int chunkNum = 
			damageData[LEFT][cx][cy] |= spikeData[dir][LEFT][(cy - baseY) * 6 + (cx - baseX) / 32] & (1 << ((cx - baseX) % 32));
			damageData[RIGHT][cx][cy] |= spikeData[dir][RIGHT][(cy - baseY) * 6 + (cx - baseX) / 32] & (1 << ((cx - baseX) % 32));
		}
	}
}

void doConveyors(playerState &p, int *conveyors, int len) {
	if (p.state != STAND && p.state != WALK && p.state != DUCK) {
		return;
	}
	
	for (int i = 0; i < len; i += 4) {
		if (p._x > (conveyors[i] << 6) - 32 &&
		p._x < (conveyors[i+1] << 6) + 32 &&
		p._y >= (conveyors[i+2] << 5) - 33 &&
		p._y < (conveyors[i+2] << 5) + 66) {
			int temp = p.vx;
			p._x += checkWalls(p, conveyors[i+3], p.state == DUCK);
			p.vx = temp;
			return;
		}
	}
}
